    if (row > row2) return 0;
    return sumCols(row, col1, col2) + sumRows(row + 1, row2, col1, col2);
  }

  private int sumCols(int row, int col, int col2) {
    if (col > col2) return 0;
    return matrix[row][col] + sumCols(row, col + 1, col2);
  }
}

